  }

  return (
    <div>
      <h2>Meal Suggestions</h2>
      <p>Age: {age}</p>
      <p>Gender: {gender}</p>
      <p>Weight: {weight}</p>
      <p>Height: {height}</p>
      <p>Activity Level: {activityLevel}</p>
      <p>Calorie Needs: {calorieNeeds} calories per day</p>
    </div>
  );
}

export default MealSuggestionsPage;
